  mt: { title: 'Katalgu tal-prodotti', subtitle: 'Oħloq prodotti u żidhom mal-katalgu. Sostnut mid-database u s-servizz tal-midja.', add: 'Żid prodott', cancelAdd: 'Ikkanċella', newProduct: 'Prodott ġdid', name: 'Isem il-prodott', price: 'Prezz', uploadPhoto: 'Illowdja ritratt', save: 'Issejvja', created: 'Il-prodott inħoloq', deleted: 'Il-prodott tħassar', storageNote: 'Ringieli fid-database, stampi fis-servizz tal-midja.', nothingFound: 'Xejn ma jaqbel ma’ din it-tfittxija.', edit: 'Editja', saveField: 'Issejvja', cancelEdit: 'Ikkanċella', fieldSaved: 'Issejvjat', baseValue: 'Bażi (Ingliż)', translation: 'Traduzzjoni', descriptionField: 'Deskrizzjoni', translations: 'Traduzzjonijiet', one: 'Prodott', back: 'Lura għall-katalgu', notFoundTitle: 'Ma teżistix prodott bħal dan', notFoundBody: 'Tħassar, jew l-indirizz huwa ħażin.', errorTitle: 'Xi ħaġa nkisret f’din il-paġna', errorBody: 'Il-katalgu nnifsu qiegħed tajjeb — dan l-iskrin falla. Erġa’ pprova.', retry: 'Erġa’ pprova' },
  ca: { title: 'Catàleg de productes', subtitle: 'Creeu productes i afegiu-los al catàleg. Recolzat per la base de dades i el servei de mèdia.', add: 'Afegeix producte', cancelAdd: 'Cancel·la', newProduct: 'Producte nou', name: 'Nom del producte', price: 'Preu', uploadPhoto: 'Puja una foto', save: 'Desa', created: 'Producte creat', deleted: 'Producte eliminat', storageNote: 'Files a la base de dades, imatges al servei de mèdia.', nothingFound: 'Res coincideix amb aquesta cerca.', edit: 'Edita', saveField: 'Desa', cancelEdit: 'Cancel·la', fieldSaved: 'Desat', baseValue: 'Base (anglès)', translation: 'Traducció', descriptionField: 'Descripció', translations: 'Traduccions', one: 'Producte', back: 'Torna al catàleg', notFoundTitle: 'Aquest producte no existeix', notFoundBody: 'S’ha eliminat, o l’adreça és incorrecta.', errorTitle: 'Alguna cosa s’ha trencat en aquesta pàgina', errorBody: 'El catàleg en si està bé — ha fallat aquesta pantalla. Torneu-ho a provar.', retry: 'Torna-ho a provar' },
  gl: { title: 'Catálogo de produtos', subtitle: 'Crea produtos e engádeos ao catálogo. Apoiado pola base de datos e o servizo de medios.', add: 'Engadir produto', cancelAdd: 'Cancelar', newProduct: 'Novo produto', name: 'Nome do produto', price: 'Prezo', uploadPhoto: 'Subir foto', save: 'Gardar', created: 'Produto creado', deleted: 'Produto eliminado', storageNote: 'Filas na base de datos, imaxes no servizo de medios.', nothingFound: 'Nada coincide con esa busca.', edit: 'Editar', saveField: 'Gardar', cancelEdit: 'Cancelar', fieldSaved: 'Gardado', baseValue: 'Base (inglés)', translation: 'Tradución', descriptionField: 'Descrición', translations: 'Traducións', one: 'Produto', back: 'Volver ao catálogo', notFoundTitle: 'Ese produto non existe', notFoundBody: 'Foi eliminado, ou o enderezo é incorrecto.', errorTitle: 'Algo fallou nesta páxina', errorBody: 'O catálogo en si está ben — fallou esta pantalla. Téntao de novo.', retry: 'Téntao de novo' },
