  ga: { title: 'Catalóg táirgí', subtitle: 'Cruthaigh táirgí agus cuir leis an gcatalóg iad. Tacaithe ag an mbunachar sonraí agus an tseirbhís meán.', add: 'Cuir táirge leis', cancelAdd: 'Cealaigh', newProduct: 'Táirge nua', name: 'Ainm an táirge', price: 'Praghas', uploadPhoto: 'Uaslódáil grianghraf', save: 'Sábháil', created: 'Táirge cruthaithe', deleted: 'Táirge scriosta', storageNote: 'Sraitheanna sa bhunachar sonraí, íomhánna sa tseirbhís meán.', nothingFound: 'Níl aon rud ag teacht leis an gcuardach sin.', edit: 'Cuir in eagar', saveField: 'Sábháil', cancelEdit: 'Cealaigh', fieldSaved: 'Sábháilte', baseValue: 'Bunleagan (Béarla)', translation: 'Aistriúchán', descriptionField: 'Cur síos', translations: 'Aistriúcháin', one: 'Táirge', back: 'Ar ais go dtí an chatalóg', notFoundTitle: 'Níl a leithéid de tháirge ann', notFoundBody: 'Scriosadh é, nó tá an seoladh mícheart.', errorTitle: 'Bhris rud éigin ar an leathanach seo', errorBody: 'Tá an chatalóg féin ceart go leor — theip ar an scáileán seo. Bain triail eile as.', retry: 'Bain triail eile as' },
