  ru: { title: "Управление каталогом", subtitle: "Слой персонала — единственное место, где товар рождается. Создайте карточку, дайте ей название и описание, прикрепите изображение из хранилища, правьте любое поле прямо в строке. Строки уходят в базу, изображения — в медиа-службу, и то и другое ваше: замените картинку в панели, и она сменится везде, где стоит. Цены — за финансами, удаление — за администрированием, и это разделение намеренное: неверное нажатие должно стоить исправления, а не потери.", add: 'Добавить продукт', cancelAdd: 'Отмена', newProduct: 'Новый продукт', name: 'Название', price: 'Цена', uploadPhoto: 'Загрузить фото', save: 'Сохранить', created: 'Продукт создан', deleted: 'Продукт удалён', storageNote: 'Строки в базе, изображения в медиа-службе.', nothingFound: 'По этому запросу ничего нет.', edit: 'Изменить', saveField: 'Сохранить', cancelEdit: 'Отмена', fieldSaved: 'Сохранено', baseValue: 'Базовое (английский)', translation: 'Перевод', descriptionField: 'Описание', translations: 'Переводы', one: 'Продукт', back: 'Назад в каталог', notFoundTitle: 'Такого продукта нет', notFoundBody: 'Он удалён, либо адрес неверный.', errorTitle: 'На этой странице что-то сломалось', errorBody: 'Сам каталог цел — не отработал этот экран. Попробуйте ещё раз.', retry: 'Повторить' },
  uk: { title: 'Каталог продуктів', subtitle: 'Створюйте продукти та додавайте їх до каталогу. Дані — у базі, зображення — у медіа-службі.', add: 'Додати продукт', cancelAdd: 'Скасувати', newProduct: 'Новий продукт', name: 'Назва продукту', price: 'Ціна', uploadPhoto: 'Завантажити фото', save: 'Зберегти', created: 'Продукт створено', deleted: 'Продукт видалено', storageNote: 'Рядки в базі, зображення в медіа-службі.', nothingFound: 'За цим запитом нічого немає.', edit: 'Змінити', saveField: 'Зберегти', cancelEdit: 'Скасувати', fieldSaved: 'Збережено', baseValue: 'Базове (англійська)', translation: 'Переклад', descriptionField: 'Опис', translations: 'Переклади', one: 'Продукт', back: 'Назад до каталогу', notFoundTitle: 'Такого продукту немає', notFoundBody: 'Його видалено, або адреса неправильна.', errorTitle: 'На цій сторінці щось зламалося', errorBody: 'Сам каталог цілий — не спрацював цей екран. Спробуйте ще раз.', retry: 'Повторити' },
