  bg: { title: 'Каталог с продукти', subtitle: 'Създавайте продукти и ги добавяйте в каталога. Данните са в базата, изображенията — в медийната услуга.', add: 'Добави продукт', cancelAdd: 'Отказ', newProduct: 'Нов продукт', name: 'Име на продукта', price: 'Цена', uploadPhoto: 'Качи снимка', save: 'Запази', created: 'Продуктът е създаден', deleted: 'Продуктът е изтрит', storageNote: 'Редове в базата, изображения в медийната услуга.', nothingFound: 'Нищо не отговаря на това търсене.', edit: 'Редактирай', saveField: 'Запази', cancelEdit: 'Отказ', fieldSaved: 'Запазено', baseValue: 'Основа (английски)', translation: 'Превод', descriptionField: 'Описание', translations: 'Преводи', one: 'Продукт', back: 'Назад към каталога', notFoundTitle: 'Такъв продукт няма', notFoundBody: 'Изтрит е, или адресът е грешен.', errorTitle: 'Нещо се счупи на тази страница', errorBody: 'Самият каталог е наред — този екран се провали. Опитайте отново.', retry: 'Опитай отново' },
  sr: { title: 'Каталог производа', subtitle: 'Креирајте производе и додајте их у каталог. Подржано базом података и медијским сервисом.', add: 'Додај производ', cancelAdd: 'Откажи', newProduct: 'Нови производ', name: 'Назив производа', price: 'Цена', uploadPhoto: 'Отпреми фотографију', save: 'Сачувај', created: 'Производ је креиран', deleted: 'Производ је обрисан', storageNote: 'Редови у бази података, слике у медијском сервису.', nothingFound: 'Ништа не одговара тој претрази.', edit: 'Измени', saveField: 'Сачувај', cancelEdit: 'Откажи', fieldSaved: 'Сачувано', baseValue: 'Основа (енглески)', translation: 'Превод', descriptionField: 'Опис', translations: 'Преводи', one: 'Производ', back: 'Назад на каталог', notFoundTitle: 'Такав производ не постоји', notFoundBody: 'Обрисан је, или је адреса погрешна.', errorTitle: 'Нешто се покварило на овој страници', errorBody: 'Сам каталог је у реду — овај екран није успео. Покушајте поново.', retry: 'Покушај поново' },
