  ku: { title: 'Katalogê berheman', subtitle: 'Berheman biafirînin û wan li katalogê zêde bikin. Ji aliyê danegeh û xizmeta medyayê ve tê piştgirîkirin.', add: 'Berhem zêde bike', cancelAdd: 'Betal bike', newProduct: 'Berhema nû', name: 'Navê berhemê', price: 'Biha', uploadPhoto: 'Wêne bar bike', save: 'Tomar bike', created: 'Berhem hate afirandin', deleted: 'Berhem hate jêbirin', storageNote: 'Rêz di danegehê de, wêne di xizmeta medyayê de.', nothingFound: 'Tiştek bi vê lêgerînê re li hev nayê.', edit: 'Biguherîne', saveField: 'Tomar bike', cancelEdit: 'Betal bike', fieldSaved: 'Hate tomarkirin', baseValue: 'Bingeh (îngilîzî)', translation: 'Werger', descriptionField: 'Danasîn', translations: 'Werger', one: 'Berhem', back: 'Vegere katalogê', notFoundTitle: 'Berhemeke wisa tune ye', notFoundBody: 'Hate jêbirin, an jî navnîşan çewt e.', errorTitle: 'Tiştek li vê rûpelê xera bû', errorBody: 'Katalog bi xwe baş e — ev ekran bi ser neket. Dîsa biceribîne.', retry: 'Dîsa biceribîne' },
